import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        long A = 0, B = 1, k = 0;

        for (long i = 1; i <= n; ++i) {
            if (i == 1) {
                A = k;
                B = i;
            }
            k = (x * i) / y;
            for (int j = 0; j <= 10; ++j) {
                long candidate_k = k + j;
                long diff1 = Math.abs(x * i - y * candidate_k);
                long diff2 = Math.abs(x * B - y * A);
                long cost1 = diff1 * y * B;
                long cost2 = diff2 * y * i;
                if (i == 1 && j == 0) {
                    // Initialize A and B
                    A = k;
                    B = i;
                }
                if (cost1 < cost2) {
                    A = candidate_k;
                    B = i;
                }
            }
        }
        long g = gcd(A, B);
        System.out.println((A / g) + "/" + (B / g));
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
